const barang = [];
const form = document.querySelector("#tambah");
const daftar = document.querySelector("#daftar");
const total = document.querySelector("#total");
function rupiah(n) {
  return `Rp${n.toLocaleString("id-ID")}`;
}
function render() {
  daftar.replaceChildren(...barang.map((b) => {
    const li = document.createElement("li");
    li.textContent = `${b.nama} - ${rupiah(b.harga)}`;
    return li;
  }));
  total.textContent = `Total ${rupiah(barang.reduce((t, b) => t + b.harga, 0))}`;
}
form.addEventListener("submit", (e) => {
  e.preventDefault();
  const data = Object.fromEntries(new FormData(form));
  barang.push({ nama: data.nama, harga: Number(data.harga) });
  form.reset();
  render();
});
render();
form.elements.nama.value = "Sepatu";
form.elements.harga.value = "250000";
form.requestSubmit();
form.elements.nama.value = "Kaos";
form.elements.harga.value = "75000";
form.requestSubmit();
